          "label": "Access",
          "type": "string",
          "description": "How much the plugin's tools may do. Generates default rules for agents with a base allow; read-only also disables GitHub's write tools.",
          "choices": [
            {
              "value": "all",
              "label": "Allowed",
              "description": "Every tool runs without asking, reads and changes alike."
            },
            {
              "value": "ask-changes",
              "label": "Ask before changes",
              "description": "Reads run without asking. Each change asks you first."
            },
            {
              "value": "read-only",
              "label": "Read only",
              "description": "Reads run. Changes never run."
            }
          ],
          "default": "all"
        },
        {
          "key": "unknownTools",
          "label": "Unknown tools",
          "type": "string",
          "description": "Whether GitHub tools this plugin does not know are listed. Listed ones follow the access rules.",
          "choices": [
            {
              "value": "ask",
              "label": "List them",
              "description": "Tools GitHub adds that this plugin does not know stay listed and follow the access rules."
            },
            {
              "value": "hide",
              "label": "Hide them",
              "description": "Tools GitHub adds that this plugin does not know are left out of the tool list."
            }
          ],
          "default": "ask"
        },
